package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string          // PIC X(4) @0 len=4
	TcF      decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string         // PIC X len=1 = "N"
var WsC decimal.Decimal     // PIC S9(3)V99 len=5 = 0
var WsFreeze int64           // PIC 99 len=2 = 0
var WsCount int64            // PIC 99 len=2 = 0
var WsFEd string             // PIC ZZ9.9 len=5
var WsCEd string             // PIC -ZZ9.99 len=7

var tempRec TempRec

// file handling
var tempLines []string
var tempIdx int

func truncateToPic(value decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	if value.IsZero() {
		// preserve zero sign as positive
		return decimal.New(0, -scale)
	}
	neg := value.Sign() < 0
	abs := value.Abs()
	// separate integer and fractional
	// We want quantized to scale (already rounded/truncated before)
	// fractional = abs - integer part
	intPart := abs.Truncate(0)
	fracPart := abs.Sub(intPart) // 0 <= frac <1
	// modulo integer part
	if intDigits > 0 {
		mod := decimal.NewFromInt(1)
		for i := 0; i < intDigits; i++ {
			mod = mod.Mul(decimal.NewFromInt(10))
		}
		// intPart mod mod
		// use DivMod via Mod
		intPart = intPart.Mod(mod)
	}
	newAbs := intPart.Add(fracPart)
	// re-quantize to scale to keep trailing zeros logic (scale handled by caller)
	if neg {
		newAbs = newAbs.Neg()
	}
	return newAbs
}

func formatZZ9dot9(v decimal.Decimal) string {
	// PIC ZZ9.9 -> intDigits=3 scale=1 width 5
	return formatEdited(v, "ZZ9.9")
}
func formatMinusZZ9dot99(v decimal.Decimal) string {
	return formatEdited(v, "-ZZ9.99")
}

func formatEdited(v decimal.Decimal, pattern string) string {
	hasSign := false
	bodyPattern := pattern
	if len(pattern) > 0 && pattern[0] == '-' {
		hasSign = true
		bodyPattern = pattern[1:]
	}
	// count intDigits and scale
	dotPos := strings.Index(bodyPattern, ".")
	intDigits := 0
	scale := 0
	if dotPos >= 0 {
		intPartPat := bodyPattern[:dotPos]
		fracPartPat := bodyPattern[dotPos+1:]
		intDigits = len(intPartPat)
		scale = len(fracPartPat)
	} else {
		intDigits = len(bodyPattern)
		scale = 0
	}
	// sign char
	signChar := ' '
	if hasSign {
		if v.Sign() < 0 && !v.IsZero() {
			// COBOL negative zero is not negative; shopspring may have -0?
			// Treat zero as positive
			signChar = '-'
		} else {
			// check if value is negative zero via original IsNegative? shopspring IsNegative false for zero
			signChar = ' '
		}
	}
	abs := v.Abs()
	// quantize abs to scale truncating (value already correct)
	// Ensure we have exactly scale fractional digits
	// Use Shift to get integer scaled
	scaled := abs.Shift(int32(scale)).Truncate(0)
	// pow10 scale
	pow10scale := decimal.NewFromInt(1)
	for i := 0; i < scale; i++ {
		pow10scale = pow10scale.Mul(decimal.NewFromInt(10))
	}
	intPartDec := decimal.NewFromInt(0)
	fracPartDec := decimal.NewFromInt(0)
	if scale > 0 {
		intPartDec = scaled.Div(pow10scale).Truncate(0)
		fracPartDec = scaled.Mod(pow10scale)
	} else {
		intPartDec = scaled
	}
	// integer part: handle overflow dropping high-order digits
	if intDigits > 0 {
		mod := decimal.NewFromInt(1)
		for i := 0; i < intDigits; i++ {
			mod = mod.Mul(decimal.NewFromInt(10))
		}
		intPartDec = intPartDec.Mod(mod)
	}
	intStr := intPartDec.StringFixed(0) // without sign
	// pad to intDigits
	if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	} else if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}
	// fractional string padded
	fracStr := ""
	if scale > 0 {
		fracStr = fracPartDec.StringFixed(0)
		if len(fracStr) < scale {
			fracStr = strings.Repeat("0", scale-len(fracStr)) + fracStr
		} else if len(fracStr) > scale {
			fracStr = fracStr[len(fracStr)-scale:]
		}
	}
	// apply Z suppression to integer part
	// need pattern for integer part: first intDigits chars of bodyPattern
	intPat := bodyPattern
	if dotPos >= 0 {
		intPat = bodyPattern[:dotPos]
	}
	suppress := true
	intRunes := []rune(intStr)
	for i := 0; i < intDigits; i++ {
		pc := intPat[i]
		if pc == 'Z' && suppress {
			if intRunes[i] == '0' {
				// if all remaining int digits are zero and the last mandatory 9 will provide zero, we blank this
				// But need to keep last 9 as 0 if everything zero: our loop will handle because last char is '9'
				intRunes[i] = ' '
			} else {
				suppress = false
			}
		} else {
			// '9' or already non-suppressed
			suppress = false
		}
	}
	intSuppressed := string(intRunes)
	var body string
	if scale > 0 {
		body = intSuppressed + "." + fracStr
	} else {
		body = intSuppressed
	}
	if hasSign {
		return string(signChar) + body
	}
	return body
}

func formatPIC99(v int64) string {
	// keep low-order 2 digits (mod 100) with sign? counts are positive
	// handle negative? but counts are non-negative modulo 100
	m := v % 100
	if m < 0 {
		m += 100
	}
	return fmt.Sprintf("%02d", m)
}

func parseTempRec(line string) TempRec {
	// pad to 8
	if len(line) < 8 {
		line = line + strings.Repeat(" ", 8-len(line))
	}
	if len(line) > 8 {
		line = line[:8]
	}
	sensor := line[0:4]
	fStr := line[4:8]
	// fStr digits only, may contain spaces
	fStrTrim := strings.TrimSpace(fStr)
	var fVal decimal.Decimal
	if fStrTrim == "" {
		fVal = decimal.NewFromInt(0)
	} else {
		// fStr is digits, implied V9
		// remove any non-digit? Should be digits
		// parse as integer then shift -1
		// if contains spaces inside, treat spaces as 0? but not needed
		clean := ""
		for _, ch := range fStr {
			if ch >= '0' && ch <= '9' {
				clean += string(ch)
			} else if ch == ' ' {
				// treat as 0? but COBOL numeric field with spaces is zero?
				// keep as is? We'll interpret blank as 0 digits
				clean += "0"
			}
		}
		if clean == "" {
			clean = "0"
		}
		// parse integer
		iv, _ := decimal.NewFromString(clean)
		fVal = iv.Shift(-1)
	}
	return TempRec{TcSensor: sensor, TcF: fVal}
}

func READ_PARA() {
	if tempIdx >= len(tempLines) {
		WsEofFlag = "Y"
		return
	}
	line := tempLines[tempIdx]
	tempIdx++
	tempRec = parseTempRec(line)
}

func PROCESS_PARA() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) * 5 / 9
	diff := tempRec.TcF.Sub(decimal.NewFromInt(32))
	mul := diff.Mul(decimal.NewFromInt(5))
	div := mul.Div(decimal.NewFromInt(9))
	rounded := div.Round(2)
	// store with overflow truncation S9(3)V99
	WsC = truncateToPic(rounded, 3, 2)

	if WsC.Sign() < 0 {
		WsFreeze = (WsFreeze + 1) % 100
	}
	WsCount = (WsCount + 1) % 100

	// MOVE TC-F TO WS-F-ED (ZZ9.9)
	WsFEd = formatEdited(tempRec.TcF, "ZZ9.9")
	// MOVE WS-C TO WS-C-ED (-ZZ9.99)
	WsCEd = formatEdited(WsC, "-ZZ9.99")

	// DISPLAY TC-SENSOR " " WS-F-ED "F " WS-C-ED "C"
	fmt.Printf("%s %sF %sC\n", tempRec.TcSensor, WsFEd, WsCEd)

	READ_PARA()
}

func MAIN_PARA() {
	// OPEN INPUT TEMP-FILE
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if !os.IsNotExist(err) {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		tempLines = []string{}
	} else {
		// LINE SEQUENTIAL: split by lines, keep each line without newline
		// Use scanner to handle both \n and \r\n
		sc := bufio.NewScanner(strings.NewReader(string(data)))
		for sc.Scan() {
			tempLines = append(tempLines, sc.Text())
		}
	}
	tempIdx = 0
	WsEofFlag = "N"
	WsC = decimal.NewFromInt(0)
	WsFreeze = 0
	WsCount = 0

	READ_PARA()
	for WsEofFlag != "Y" {
		PROCESS_PARA()
	}
	// CLOSE TEMP-FILE (no op)
	// DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", formatPIC99(WsCount), formatPIC99(WsFreeze))
}

func main() {
	MAIN_PARA()
}
